/** static void ExpandBattleTextBuffPlaceholders(const u8 *src, u8 *dst) */
export function ExpandBattleTextBuffPlaceholders(src: any, dst: any): any {
  let srcID: any = 1;
      let value: any = 0;
      let text: any = [];
      let hword: any = null;

      dst = (0xFF);
      while (src[srcID] != (0xFF))
      {
          switch (src[srcID])
          {
          case (0):  
              hword = T1_READ_16(src[srcID + 1]);
              if (hword == (209) || hword == (211))
                  srcID += 3;
              StringAppend(dst, gBattleStringsTable[hword - ((12))]);
              srcID += 3;
              break;
          case (1):  
              switch (src[srcID + 1])
              {
              case 1:
                  value = src[srcID + 3];
                  break;
              case 2:
                  value = T1_READ_16(src[srcID + 3]);
                  break;
              case 4:
                  value = T1_READ_32(src[srcID + 3]);
                  break;
              }
              ConvertIntToDecimalStringN(dst, value, STR_CONV_MODE_LEFT_ALIGN, src[srcID + 2]);
              srcID += src[srcID + 1] + 3;
              break;
          case (2):  
              StringAppend(dst, gMoveNames[T1_READ_16(src[srcID + 1])]);
              srcID += 3;
              break;
          case (3):  
              StringAppend(dst, gTypeNames[src[srcID + 1]]);
              srcID += 2;
              break;
          case (4):  
              if (GetBattlerSide(src[srcID + 1]) == (0))
              {
                  GetMonData(gPlayerParty[src[srcID + 2]], MON_DATA_NICKNAME, text);
                  StringGet_Nickname(text);
                  StringAppend(dst, text);
              }
              else
              {
                  GetMonData(gEnemyParty[src[srcID + 2]], MON_DATA_NICKNAME, dst);
                  StringGet_Nickname(dst);
                  if (gBattleTypeFlags & ((1 << 3)))
                      StringAppend(dst, sText_FoePkmnPrefix);
                  else
                      StringAppend(dst, sText_WildPkmnPrefix);
              }
              srcID += 3;
              break;
          case (5):  
              StringAppend(dst, gStatNamesTable[src[srcID + 1]]);
              srcID += 2;
              break;
          case (6):  
              GetSpeciesName(dst, T1_READ_16(src[srcID + 1]));
              srcID += 3;
              break;
          case (7):  
              if (GetBattlerSide(src[srcID + 1]) == (0))
                  GetMonData(gPlayerParty[src[srcID + 2]], MON_DATA_NICKNAME, dst);
              else
                  GetMonData(gEnemyParty[src[srcID + 2]], MON_DATA_NICKNAME, dst);
              StringGet_Nickname(dst);
              srcID += 3;
              break;
          case (8):  
              StringAppend(dst, gPokeblockWasTooXStringTable[src[srcID + 1]]);
              srcID += 2;
              break;
          case (9):  
              StringAppend(dst, gAbilityNames[src[srcID + 1]]);
              srcID += 2;
              break;
          case (10):  
              hword = T1_READ_16(src[srcID + 1]);
              if (gBattleTypeFlags & (((1 << 1)) | ((1 << 25))))
              {
                  if (hword == (175))
                  {
                      CopyItemName(hword, dst);
                  }
                  else
                  {
                      CopyItemName(hword, dst);
                  }
              }
              else
              {
                  CopyItemName(hword, dst);
              }
              srcID += 3;
              break;
          }
      }
}

/** static void ChooseMoveUsedParticle(u8 *textBuff) */
export function ChooseMoveUsedParticle(textBuff: any): any {
  let counter: any = 0;
      let i: any = 0;

      while (counter != (4))
      {
          if (sGrammarMoveUsedTable[i] == 0)
              counter++;
          if (sGrammarMoveUsedTable[i++] == gBattleMsgDataPtr.currentMove)
              break;
      }

      if (counter >= 0)
      {
          if (counter <= 2)
              StringCopy(textBuff, sText_SpaceIs);  
          else if (counter <= (4))
              StringCopy(textBuff, sText_ApostropheS);  
      }
}

/** static void ChooseTypeOfMoveUsedString(u8 *dst) */
export function ChooseTypeOfMoveUsedString(dst: any): any {
  let counter: any = 0;
      let i: any = 0;

      while (dst != (0xFF))
          dst++;

      while (counter != (4))
      {
          if (sGrammarMoveUsedTable[i] == (0))
              counter++;
          if (sGrammarMoveUsedTable[i++] == gBattleMsgDataPtr.currentMove)
              break;
      }

      switch (counter)
      {
      case 0:
          StringCopy(dst, sText_ExclamationMark);
          break;
      case 1:
          StringCopy(dst, sText_ExclamationMark2);
          break;
      case 2:
          StringCopy(dst, sText_ExclamationMark3);
          break;
      case 3:
          StringCopy(dst, sText_ExclamationMark4);
          break;
      case 4:
          StringCopy(dst, sText_ExclamationMark5);
          break;
      }
}

/** void BattlePutTextOnWindow(const u8 *text, u8 windowId) */
export function BattlePutTextOnWindow(text: any, windowId: any): any {
  let textInfo: any = sBattleTextOnWindowsInfo[gBattleScripting.windowsType];
      let copyToVram: any = null;
      let printerTemplate: any = null;
      let speed: any = null;

      if (windowId & ((1 << 7)))
      {
          windowId &= ~((1 << 7));
          copyToVram = FALSE;
      }
      else
      {
          FillWindowPixelBuffer(windowId, textInfo[windowId].fillValue);
          copyToVram = TRUE;
      }

      printerTemplate.currentChar = text;
      printerTemplate.windowId = windowId;
      printerTemplate.fontId = textInfo[windowId].fontId;
      printerTemplate.x = textInfo[windowId].x;
      printerTemplate.y = textInfo[windowId].y;
      printerTemplate.currentX = printerTemplate.x;
      printerTemplate.currentY = printerTemplate.y;
      printerTemplate.letterSpacing = textInfo[windowId].letterSpacing;
      printerTemplate.lineSpacing = textInfo[windowId].lineSpacing;
      printerTemplate.unk = 0;
      printerTemplate.fgColor = textInfo[windowId].fgColor;
      printerTemplate.bgColor = textInfo[windowId].bgColor;
      printerTemplate.shadowColor = textInfo[windowId].shadowColor;

      if (printerTemplate.x == 0xFF)
      {
          let width: any = GetBattleWindowTemplatePixelWidth(gBattleScripting.windowsType, windowId);
          let alignX: any = GetStringCenterAlignXOffsetWithLetterSpacing(printerTemplate.fontId, printerTemplate.currentChar, width, printerTemplate.letterSpacing);
          printerTemplate.x = printerTemplate.currentX = alignX;
      }

      if (windowId == (22))
          gTextFlags.useAlternateDownArrow = FALSE;
      else
          gTextFlags.useAlternateDownArrow = TRUE;

      if (gBattleTypeFlags & (((1 << 1)) | ((1 << 24))))
          gTextFlags.autoScroll = TRUE;
      else
          gTextFlags.autoScroll = FALSE;

      if (windowId == (0) || windowId == (22))
      {
          if (gBattleTypeFlags & (((1 << 1)) | ((1 << 25))))
              speed = 1;
          else if (gBattleTypeFlags & ((1 << 24)))
              speed = sRecordedBattleTextSpeeds[GetTextSpeedInRecordedBattle()];
          else
              speed = GetPlayerTextSpeedDelay();

          gTextFlags.canABSpeedUpPrint = 1;
      }
      else
      {
          speed = textInfo[windowId].speed;
          gTextFlags.canABSpeedUpPrint = 0;
      }

      AddTextPrinter(printerTemplate, speed, NULL);

      if (copyToVram)
      {
          PutWindowTilemap(windowId);
          CopyWindowToVram(windowId, COPYWIN_FULL);
      }
}

/** void SetPpNumbersPaletteInMoveSelection(void) */
export function SetPpNumbersPaletteInMoveSelection(): any {
  let chooseMoveStruct: any = (gBattleBufferA[gActiveBattler][4]);
      let palPtr: any = gPPTextPalette;
      let _var: any = GetCurrentPpToMaxPpState(chooseMoveStruct.currentPp[gMoveSelectionCursor[gActiveBattler]],
                           chooseMoveStruct.maxPp[gMoveSelectionCursor[gActiveBattler]]);

      gPlttBufferUnfaded[BG_PLTT_ID(5) + 12] = palPtr[(_var * 2) + 0];
      gPlttBufferUnfaded[BG_PLTT_ID(5) + 11] = palPtr[(_var * 2) + 1];

      CpuCopy16(gPlttBufferUnfaded[BG_PLTT_ID(5) + 12],gPlttBufferFaded[BG_PLTT_ID(5) + 12], PLTT_SIZEOF(1));
      CpuCopy16(gPlttBufferUnfaded[BG_PLTT_ID(5) + 11],gPlttBufferFaded[BG_PLTT_ID(5) + 11], PLTT_SIZEOF(1));
}

/** u8 GetCurrentPpToMaxPpState(u8 currentPp, u8 maxPp) */
export function GetCurrentPpToMaxPpState(currentPp: any, maxPp: any): any {
  if (maxPp == currentPp)
      {
          return 3;
      }
      else if (maxPp <= 2)
      {
          if (currentPp > 1)
              return 3;
          else
              return 2 - currentPp;
      }
      else if (maxPp <= 7)
      {
          if (currentPp > 2)
              return 3;
          else
              return 2 - currentPp;
      }
      else
      {
          if (currentPp == 0)
              return 2;
          if (currentPp <= maxPp / 4)
              return 1;
          if (currentPp > maxPp / 2)
              return 3;
      }

      return 0;
}

